// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        uint256 balBefore = c.tokenBalance(caller);
        if (balBefore != 0) return;

        vm.prank(caller);
        try c.airDrop() {
            // For the reference, airDrop must never succeed for an unauthenticated
            // zero-balance caller: supportsToken would reject any EOA caller.
            assertTrue(c.tokenBalance(caller) == 0);
        } catch {
            assertTrue(c.tokenBalance(caller) == 0);
        }
    }
}
